def log_resolution(ax, lower=.5):
    ax.set_xscale('log')
    ax.set_xlim(lower, 20)
    ticks = [value for value in (.1, .2, .5, 1, 2, 5, 10, 20) if value >= lower]
    ax.xaxis.set_major_locator(FixedLocator(ticks))
    ax.xaxis.set_major_formatter(FuncFormatter(lambda value, pos: f'{value:g}'))
    ax.xaxis.set_minor_formatter(NullFormatter())
    hp.frame_axes(ax, minor=False)


def physical_square_contours(mass, u, kappa):
    """Rank density in physical coordinates using full-support probability mass."""
    from prior_sensitivity import physical
    q = physical(u)
    unit_density = mass/(base.geometry.weights(u)[:, None]*base.geometry.weights(kappa)[None, :])
    jacobian = np.zeros_like(u)
    jacobian[1:-1] = (2/(3*np.pi))*q[1:-1]**(-2/3)/(1+q[1:-1]**(2/3))
    # The origin's integrable singularity is represented by its finite cell
    # average. At infinity the physical density tends to zero.
    jacobian[0] = base.geometry.weights(u)[0]/physical(.5*(u[0]+u[1]))
    density = unit_density*jacobian[:, None]
    order = np.argsort(density.ravel())[::-1]
    cumulative = np.cumsum(mass.ravel()[order])
    levels = [float(density.ravel()[order[np.searchsorted(cumulative, p)]]) for p in (.95, .68)]
    enclosed = [float(mass[density >= level].sum()) for level in levels]
    return q, density, levels, enclosed

